198		report := traceOf(t, `{"datasets":[
199			{"name":"T","upstreams":["0a","A"]},
200			{"name":"A","upstreams":["Z"]},
201			{"name":"Z","upstreams":["R"]},
202			{"name":"0a","upstreams":["0b"]},
203			{"name":"0b","upstreams":["0c"]},
204			{"name":"0c","upstreams":["R"]},
205			{"name":"R","upstreams":[]}
206		]}`, "T")
