295	// TestTraceDeterministicAcrossEquivalentDeepSnapshots is the deep version of
296	// the determinism guarantee: record order, upstream order, duplicate
297	// upstreams, and whitespace reshuffle a graph with converging branches and
298	// multiple post-merge roots, yet every path choice stays identical.
299	func TestTraceDeterministicAcrossEquivalentDeepSnapshots(t *testing.T) {
300		variants := []string{
301			// Canonical-ish order: T with two branches merging at M, M reaching
302			// two roots, plus a disconnected branch.
303			`{"datasets":[
304				{"name":"T","upstreams":["B","A"]},
305				{"name":"A","upstreams":["Z"]},
306				{"name":"Z","upstreams":["M"]},
307				{"name":"B","upstreams":["C"]},
308				{"name":"C","upstreams":["M"]},
309				{"name":"M","upstreams":["R2","R1"]},
310				{"name":"R1","upstreams":[]},
311				{"name":"R2","upstreams":[]},
312				{"name":"U","upstreams":["X"]},
313				{"name":"X","upstreams":[]}
314			]}`,
315			// Same semantics: records reversed, upstream lists reordered with
316			// duplicates, whitespace changed.
317			`{ "datasets" : [
318				{"upstreams":[],"name":"X"},
319				{"name":"U","upstreams":["X","X"]},
320				{"upstreams":[],"name":"R2"},
321				{"name":"R1","upstreams":[]},
322				{"upstreams":["R1","R2","R1"],"name":"M"},
323				{"name":"C","upstreams":["M","M"]},
324				{"upstreams":["M"],"name":"Z"},
325				{"name":"B","upstreams":["C"]},
326				{"name":"A","upstreams":["Z"]},
327				{"upstreams":["A","B","B","A"],"name":"T"}
328			] }`,
329		}
330		var want *TraceReport
331		for i, in := range variants {
332			report := traceOf(t, in, "T")
333			if i == 0 {
334				want = report
335				continue
336			}
337			if !reflect.DeepEqual(report, want) {
338				t.Errorf("variant %d report = %+v, want %+v", i, report, want)
339			}
340		}
341		// Pin the expected choice once so the determinism check cannot pass while
342		// both variants make the same wrong selection.
343		wantSources := []SourceTrace{
344			{Root: "R1", Path: []string{"T", "A", "Z", "M", "R1"}},
345			{Root: "R2", Path: []string{"T", "A", "Z", "M", "R2"}},
346		}
347		if !reflect.DeepEqual(want.Sources, wantSources) {
348			t.Errorf("Sources = %+v, want %+v", want.Sources, wantSources)
349		}
350		if want.ContentID == "" || want.Dataset != "T" {
351			t.Errorf("report metadata = contentId %q dataset %q, want snapshot id and %q", want.ContentID, want.Dataset, "T")
352		}
353	}
354	
355	// TestTraceReportCarriesContentIDAndQueryDeep pins, for a deep graph, that
356	// the report's identifiers come from the snapshot actually read and from the
357	// query as typed — never from whichever input record appeared first.
358	func TestTraceReportCarriesContentIDAndQueryDeep(t *testing.T) {
359		in := `{"datasets":[
360			{"name":"R","upstreams":[]},
361			{"name":"M","upstreams":["R"]},
362			{"name":"Z","upstreams":["M"]},
363			{"name":"A","upstreams":["Z"]},
364			{"name":"T","upstreams":["A"]}
365		]}`
366		snap := snapshotOf(t, in)
367		report, err := TraceSources(snap, "T")
368		if err != nil {
369			t.Fatalf("TraceSources: %v", err)
370		}
371		if report.ContentID != snap.ContentID {
372			t.Errorf("ContentID = %q, want %q", report.ContentID, snap.ContentID)
373		}
374		if report.Dataset != "T" {
375			t.Errorf("Dataset = %q, want %q", report.Dataset, "T")
376		}
377		want := []SourceTrace{{Root: "R", Path: []string{"T", "A", "Z", "M", "R"}}}
378		if !reflect.DeepEqual(report.Sources, want) {
379			t.Errorf("Sources = %+v, want %+v; path must not depend on record order", report.Sources, want)
380		}
381	}
382	
383	// TestTraceSnapshotIsTheOnlySource pins the version semantics: the trace is
384	// computed from the snapshot alone, so mutating the live graph afterwards
385	// cannot change what the frozen version reports.
386	func TestTraceSnapshotIsTheOnlySource(t *testing.T) {
387		graph := graphFromJSON(t, `{"datasets":[{"name":"T","upstreams":["R"]},{"name":"R","upstreams":[]}]}`)
388		snap, err := BuildSnapshot(graph)
389		if err != nil {
390			t.Fatalf("BuildSnapshot: %v", err)
391		}
392		// Rewire the live graph after the snapshot was frozen.
393		if err := Register(graph, Dataset{Name: "S"}, nil); err != nil {
394			t.Fatalf("Register S: %v", err)
395		}
396		if err := Register(graph, Dataset{Name: "T"}, []string{"S"}); err != nil {
397			t.Fatalf("rewire T: %v", err)
398		}
399		report, err := TraceSources(snap, "T")
400		if err != nil {
401			t.Fatalf("TraceSources: %v", err)
402		}
403		want := []SourceTrace{{Root: "R", Path: []string{"T", "R"}}}
404		if !reflect.DeepEqual(report.Sources, want) {
405			t.Errorf("Sources = %+v, want frozen %+v", report.Sources, want)
406		}
407	}
