224							t.Fatalf("entry for %q vanished after editing %q", want.Dataset, target)
225						}
226						if !reflect.DeepEqual(got, want) {
227							t.Errorf("entry for %q changed when %q was edited:\n got %+v\nwant %+v", want.Dataset, target, got, want)
228						}
229					}
230	
231					// The edited entry's OTHER side is untouched (the edit must not
232					// share backing storage between old and new root arrays).
233					gotEdited, ok := rootChangeFor(report, editedName)
234					if !ok {
235						t.Fatalf("edited entry for %q vanished (renamed=%v)", target, editedName)
236					}
237					if editName != "rewrite old roots in place and append" {
238						if !reflect.DeepEqual(gotEdited.OldRoots, otherSideBefore.old) {
239							t.Errorf("edited entry OldRoots = %v, want untouched %v", gotEdited.OldRoots, otherSideBefore.old)
240						}
241					}
242					if editName != "rewrite new roots in place and append" {
243						if !reflect.DeepEqual(gotEdited.NewRoots, otherSideBefore.new) {
244							t.Errorf("edited entry NewRoots = %v, want untouched %v", gotEdited.NewRoots, otherSideBefore.new)
245						}
246					}
247	
248					// The independently returned report is the complete original.
249					if !reflect.DeepEqual(oracle.RootSourceChanges, wantIntersectRootChanges) {
250						t.Errorf("separate report root changes = %v, want %v", oracle.RootSourceChanges, wantIntersectRootChanges)
251					}
252					// The input snapshots are untouched too.
253					if got := snapshotDatasetsCopy(oldSnap); !reflect.DeepEqual(got, snapshotDatasetsCopy(snapshotOf(t, intersectRootsOldGraph))) {
254						t.Errorf("old snapshot changed after editing a report entry: %v", got)
255					}
256					if got := snapshotDatasetsCopy(newSnap); !reflect.DeepEqual(got, snapshotDatasetsCopy(snapshotOf(t, intersectRootsNewGraph))) {
257						t.Errorf("new snapshot changed after editing a report entry: %v", got)
258					}
259				})
260			}
261		}
262	}
263	
264	// indexOfRootChange returns the first index of an entry whose Dataset equals
265	// name, or -1.
266	func indexOfRootChange(report *CompareReport, name string) int {
267		for i := range report.RootSourceChanges {
268			if report.RootSourceChanges[i].Dataset == name {
269				return i
270			}
271		}
272		return -1
273	}
274	
275	// TestCompareTwoReportsOfSamePairAreIndependent thoroughly edits one report
276	// (in-place rewrites, appends, swaps, and pruning across every list kind) and
277	// verifies the other report still describes the complete original diff, while
278	// both input snapshots keep names, upstreams, content ids, and export bytes.
279	// Comparing the same pair again afterwards reproduces the original report,
280	// including its JSON bytes.
281	func TestCompareTwoReportsOfSamePairAreIndependent(t *testing.T) {
282		oldSnap := snapshotOf(t, intersectRootsOldGraph)
283		newSnap := snapshotOf(t, intersectRootsNewGraph)
284		first := CompareSnapshots(oldSnap, newSnap)
285		second := CompareSnapshots(oldSnap, newSnap)
286		oracle := CompareSnapshots(snapshotOf(t, intersectRootsOldGraph), snapshotOf(t, intersectRootsNewGraph))
287	
288		wantBytes := mustMarshalCompareReport(t, oracle)
289		oldBytesBefore := mustMarshalSnapshot(t, oldSnap)
290		newBytesBefore := mustMarshalSnapshot(t, newSnap)
291		oldDatasetsBefore := snapshotDatasetsCopy(oldSnap)
292		newDatasetsBefore := snapshotDatasetsCopy(newSnap)
293		oldID, newID := oldSnap.ContentID, newSnap.ContentID
294	
295		// Rewrite, reorder, append, and prune every list kind in the first report.
296		first.NewDatasets[0] = "HACK"
297		first.NewDatasets = append(first.NewDatasets, "GHOST")
298		first.RemovedDatasets[0], first.RemovedDatasets[len(first.RemovedDatasets)-1] =
299			first.RemovedDatasets[len(first.RemovedDatasets)-1], first.RemovedDatasets[0]
300		first.RemovedDatasets[1] = "HACK"
301		first.ChangedDatasets = first.ChangedDatasets[:1]
302		first.ChangedDatasets[0] = "HACK"
303		first.AddedRelations[0], first.AddedRelations[1] = first.AddedRelations[1], first.AddedRelations[0]
304		first.AddedRelations[0].Upstream = "HACK"
305		first.AddedRelations[0].Downstream = "GHOST"
306		first.AddedRelations = append(first.AddedRelations, Relation{Upstream: "FAKE", Downstream: "FAKE"})
307		first.RemovedRelations = first.RemovedRelations[:2]
308		first.RemovedRelations[1].Downstream = "GHOST"
309		// Swap the root-change entries, edit through the swapped position, prune.
310		first.RootSourceChanges[0], first.RootSourceChanges[2] = first.RootSourceChanges[2], first.RootSourceChanges[0]
311		first.RootSourceChanges[0].OldRoots[0] = "HACK"
312		first.RootSourceChanges[0].NewRoots = append(first.RootSourceChanges[0].NewRoots, "GHOST")
313		first.RootSourceChanges[0].Dataset = "DISPLAY"
314		first.RootSourceChanges = first.RootSourceChanges[:1]
315	
316		// The edit really landed on the first copy.
317		if !reflect.DeepEqual(first.RootSourceChanges, []RootSourceChange{
318			{Dataset: "DISPLAY", OldRoots: []string{"HACK", "R2", "R3"}, NewRoots: []string{"R2", "R3", "R4", "GHOST"}},
319		}) {
320			t.Fatalf("test setup: first report edit had no expected effect: %+v", first.RootSourceChanges)
321		}
322	
323		// The untouched report is the complete original diff.
324		if !reflect.DeepEqual(second, oracle) {
325			t.Errorf("second report differs from the original after editing the first:\n got %#v\nwant %#v", second, oracle)
326		}
327		if got := mustMarshalCompareReport(t, second); !bytes.Equal(got, wantBytes) {
328			t.Errorf("second report JSON moved with the first:\n got %s\nwant %s", got, wantBytes)
329		}
330	
331		// Both input snapshots are unchanged: content id, graph records, bytes.
332		if oldSnap.ContentID != oldID || newSnap.ContentID != newID {
333			t.Errorf("an input content id moved: old=%q want %q, new=%q want %q",
334				oldSnap.ContentID, oldID, newSnap.ContentID, newID)
335		}
336		if got := snapshotDatasetsCopy(oldSnap); !reflect.DeepEqual(got, oldDatasetsBefore) {
337			t.Errorf("old snapshot records changed during/after comparison:\n got %v\nwant %v", got, oldDatasetsBefore)
338		}
339		if got := snapshotDatasetsCopy(newSnap); !reflect.DeepEqual(got, newDatasetsBefore) {
340			t.Errorf("new snapshot records changed during/after comparison:\n got %v\nwant %v", got, newDatasetsBefore)
341		}
342		if got := mustMarshalSnapshot(t, oldSnap); !bytes.Equal(got, oldBytesBefore) {
343			t.Errorf("old snapshot bytes changed:\n got %s\nwant %s", got, oldBytesBefore)
344		}
345		if got := mustMarshalSnapshot(t, newSnap); !bytes.Equal(got, newBytesBefore) {
346			t.Errorf("new snapshot bytes changed:\n got %s\nwant %s", got, newBytesBefore)
347		}
348	
349		// Comparing the same pair again still reproduces the original result and
350		// its exact JSON bytes.
351		again := CompareSnapshots(oldSnap, newSnap)
352		if !reflect.DeepEqual(again, oracle) {
353			t.Errorf("re-comparison differs from the original report:\n got %#v\nwant %#v", again, oracle)
354		}
355		if got := mustMarshalCompareReport(t, again); !bytes.Equal(got, wantBytes) {
356			t.Errorf("re-comparison JSON differs:\n got %s\nwant %s", got, wantBytes)
357		}
358	}
359	
360	// TestCompareEarlierReportFreezesAcrossLaterEditsAndOtherPairs verifies the
361	// time direction: once a report has been returned, the caller editing the
362	// snapshot records it still holds — or comparing a different legal pair —
363	// cannot move the recorded diff. The compare interface is not extended for
364	// the edited snapshots; only the already returned result is pinned.
365	func TestCompareEarlierReportFreezesAcrossLaterEditsAndOtherPairs(t *testing.T) {
366		oldSnap := snapshotOf(t, intersectRootsOldGraph)
367		newSnap := snapshotOf(t, intersectRootsNewGraph)
368		earlier := CompareSnapshots(oldSnap, newSnap)
369		earlierBytes := mustMarshalCompareReport(t, earlier)
370	
371		// The caller reorganizes its own snapshot records for display after the
372		// report returned: repoint in place, append a ghost upstream, rename a
373		// record (the documents are now the caller's edited copies — no repair is
374		// expected of the compare interface).
375		iShared := snapshotDatasetIndex(oldSnap, "shared")
376		oldSnap.Graph.Datasets[iShared].Upstreams[0] = "HACK"
377		oldSnap.Graph.Datasets[iShared].Upstreams = append(oldSnap.Graph.Datasets[iShared].Upstreams, "ghost")
378		iD2 := snapshotDatasetIndex(newSnap, "D2")
379		newSnap.Graph.Datasets[iD2].Name = "DISPLAY"
380		if got := mustMarshalCompareReport(t, earlier); !bytes.Equal(got, earlierBytes) {
381			t.Fatalf("test setup: earlier report already moved:\n got %s\nwant %s", got, earlierBytes)
382		}
383	
384		// Comparing a different, legal pair must not touch the held report.
385		otherOld := snapshotOf(t, `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`)
386		otherNew := snapshotOf(t, `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":[]}]}`)
387		other := CompareSnapshots(otherOld, otherNew)
388		if got, want := other.ChangedDatasets, []string{"B"}; !reflect.DeepEqual(got, want) {
389			t.Fatalf("sanity: other-pair ChangedDatasets = %v, want %v", got, want)
390		}
391		if got, want := other.RootSourceChanges, []RootSourceChange{
392			{Dataset: "B", OldRoots: []string{"A"}, NewRoots: []string{"B"}},
393		}; !reflect.DeepEqual(got, want) {
394			t.Fatalf("sanity: other-pair root changes = %v, want %v", got, want)
395		}
396	
397		if got := mustMarshalCompareReport(t, earlier); !bytes.Equal(got, earlierBytes) {
398			t.Errorf("earlier report changed after editing inputs and comparing another pair:\n got %s\nwant %s", got, earlierBytes)
399		}
400		if !reflect.DeepEqual(earlier.RootSourceChanges, wantIntersectRootChanges) {
401			t.Errorf("earlier root changes = %v, want %v", earlier.RootSourceChanges, wantIntersectRootChanges)
402		}
403	
404		// Comparing the caller's now-edited pair still has no write-back into the
405		// held report.
406		_ = CompareSnapshots(oldSnap, newSnap)
407		if got := mustMarshalCompareReport(t, earlier); !bytes.Equal(got, earlierBytes) {
408			t.Errorf("earlier report changed after re-comparing the edited pair:\n got %s\nwant %s", got, earlierBytes)
409		}
410	}
411	
412	// TestCompareEmptyResultIsIndependentAndCarriesNoResidue verifies that a diff
413	// with no changes gets its own fresh result: after a non-empty comparison, the
414	// empty lists are zero-length, non-nil, serialize as [], and contain no name
415	// seen in the earlier report. Editing either empty report afterwards cannot
416	// move the other one, and a further identical comparison stays empty.
417	func TestCompareEmptyResultIsIndependentAndCarriesNoResidue(t *testing.T) {
418		oldSnap := snapshotOf(t, intersectRootsOldGraph)
419		newSnap := snapshotOf(t, intersectRootsNewGraph)
420		nonEmpty := CompareSnapshots(oldSnap, newSnap)
421		if len(nonEmpty.RootSourceChanges) == 0 {
422			t.Fatalf("test setup: headline comparison produced no changes")
423		}
424		// Display-edit the non-empty report; residue must not leak from it either.
425		nonEmpty.RootSourceChanges[0].OldRoots[0] = "HACK"
426		nonEmpty.NewDatasets = append(nonEmpty.NewDatasets, "GHOST")
427	
428		identical := snapshotOf(t, intersectRootsOldGraph)
429		empty := CompareSnapshots(identical, identical)
430		assertEmptyReport(t, empty)
431	
432		emptyJSON := string(mustMarshalCompareReport(t, empty))
433		for _, key := range []string{`"newDatasets":`, `"removedDatasets":`, `"changedDatasets":`, `"addedRelations":`, `"removedRelations":`, `"rootSourceChanges":`} {
434			if !strings.Contains(emptyJSON, key+"[]") {
435				t.Errorf("empty report key %s not encoded as []:\n%s", key, emptyJSON)
436			}
437		}
438		for _, leftover := range []string{"R1", "R4", "shared", "b1", "a2", "HACK", "GHOST"} {
439			if strings.Contains(emptyJSON, leftover) {
440				t.Errorf("empty report carries a leftover entry %q from an earlier comparison:\n%s", leftover, emptyJSON)
441			}
442		}
443	
444		// Two empty results are independent as well: appending a display entry to
445		// one must not give the other any content.
446		emptyToo := CompareSnapshots(identical, identical)
447		empty.NewDatasets = append(empty.NewDatasets, "GHOST")
448		empty.RootSourceChanges = append(empty.RootSourceChanges, RootSourceChange{Dataset: "FAKE"})
449		assertEmptyReport(t, emptyToo)
450	
451		// A further identical comparison, after the edits, is still its own empty
452		// result with the same JSON bytes.
453		emptyAgain := CompareSnapshots(identical, identical)
454		assertEmptyReport(t, emptyAgain)
455		if got := mustMarshalCompareReport(t, emptyAgain); !strings.Contains(string(got), `"rootSourceChanges":[]`) {
456			t.Errorf("repeated empty comparison did not encode []:\n%s", got)
457		}
458	}
459	
460	// TestCompareReportBytesUnaffectedByRecordOrderAndDuplicates feeds the
461	// headline scenario in shuffled form with shuffled and repeated upstreams;
462	// the unedited report must come out content- and byte-identical to the
463	// canonical comparison, with verbatim case/space name spellings in the
464	// root-source entries and the existing byte-order sorting on every list.
465	func TestCompareReportBytesUnaffectedByRecordOrderAndDuplicates(t *testing.T) {
466		oldCanonical := snapshotOf(t, intersectRootsOldGraph)
467		newCanonical := snapshotOf(t, intersectRootsNewGraph)
468		wantBytes := mustMarshalCompareReport(t, CompareSnapshots(oldCanonical, newCanonical))
469		oldBytesBefore := mustMarshalSnapshot(t, oldCanonical)
470		newBytesBefore := mustMarshalSnapshot(t, newCanonical)
471	
472		// Same semantics as the headline fixtures: records shuffled, upstream
473		// lists shuffled and repeated, including D1's multipath dependency.
474		oldShuffled := snapshotOf(t, `{"datasets":[
475			{"name":"D2","upstreams":["shared"]},
476			{"upstreams":["shared","a1","a1"],"name":"D1"},
477			{"upstreams":["a2","a1","a2"],"name":"shared"},
478			{"name":"a2","upstreams":["R3","R2"]},
479			{"upstreams":["R2","R1","R1"],"name":"a1"},
480			{"name":"R3","upstreams":[]},
481			{"name":"R2","upstreams":[]},
482			{"name":"R1","upstreams":[]}
483		]}`)
484		newShuffled := snapshotOf(t, `{"datasets":[
485			{"upstreams":["shared"],"name":"D2"},
486			{"name":"D1","upstreams":["shared","b1","b1"]},
487			{"upstreams":["b2","b1","b2"],"name":"shared"},
488			{"upstreams":["R4","R3"],"name":"b2"},
489			{"name":"b1","upstreams":["R4","R2","R2"]},
490			{"name":"R4","upstreams":[]},
491			{"name":"R3","upstreams":[]},
492			{"name":"R2","upstreams":[]}
493		]}`)
494	
495		report := CompareSnapshots(oldShuffled, newShuffled)
496		if got := mustMarshalCompareReport(t, report); !bytes.Equal(got, wantBytes) {
497			t.Fatalf("shuffled/duplicated inputs produced a different report:\n got %s\nwant %s", got, wantBytes)
498		}
499		if !reflect.DeepEqual(report.RootSourceChanges, wantIntersectRootChanges) {
500			t.Errorf("shuffled inputs root changes = %v, want %v", report.RootSourceChanges, wantIntersectRootChanges)
501		}
502	
503		// Comparison stayed read-only on the canonical snapshots handed in.
504		if got := mustMarshalSnapshot(t, oldCanonical); !bytes.Equal(got, oldBytesBefore) {
505			t.Errorf("old snapshot bytes changed during comparison:\n got %s\nwant %s", got, oldBytesBefore)
506		}
507		if got := mustMarshalSnapshot(t, newCanonical); !bytes.Equal(got, newBytesBefore) {
508			t.Errorf("new snapshot bytes changed during comparison:\n got %s\nwant %s", got, newBytesBefore)
509		}
510	
511		// Editing the shuffled-input report's first entry cannot rewrite the
512		// verbatim spellings a second report carries — here with case/space names.
513		caseOld := snapshotOf(t, `{"datasets":[
514			{"name":" A ","upstreams":[]},
515			{"name":"a","upstreams":[]},
516			{"name":"A","upstreams":[]},
517			{"name":"M","upstreams":[" A ","a"]},
518			{"name":"n","upstreams":["M"]}
519		]}`)
520		caseNew := snapshotOf(t, `{"datasets":[
521			{"name":" A ","upstreams":[]},
522			{"name":"a","upstreams":[]},
523			{"name":"A","upstreams":[]},
524			{"name":"M","upstreams":["A"]},
525			{"name":"n","upstreams":["M"]}
526		]}`)
527		first := CompareSnapshots(caseOld, caseNew)
528		second := CompareSnapshots(caseOld, caseNew)
529		secondBytes := mustMarshalCompareReport(t, second)
530		wantCaseChanges := []RootSourceChange{
531			{Dataset: "M", OldRoots: []string{" A ", "a"}, NewRoots: []string{"A"}},
532			{Dataset: "n", OldRoots: []string{" A ", "a"}, NewRoots: []string{"A"}},
533		}
534		if !reflect.DeepEqual(first.RootSourceChanges, wantCaseChanges) {
535			t.Fatalf("case/space root changes = %v, want %v", first.RootSourceChanges, wantCaseChanges)
536		}
537		first.RootSourceChanges[0].OldRoots[0] = "trimmed"
538		first.RootSourceChanges[0].OldRoots = append(first.RootSourceChanges[0].OldRoots, "HACK")
539		first.RootSourceChanges[0].Dataset = "HACK"
540		if !reflect.DeepEqual(second.RootSourceChanges, wantCaseChanges) {
541			t.Errorf("case/space spellings moved into the other report: %v", second.RootSourceChanges)
542		}
543		if got := mustMarshalCompareReport(t, second); !bytes.Equal(got, secondBytes) {
544			t.Errorf("case/space report JSON changed after editing the first:\n got %s\nwant %s", got, secondBytes)
545		}
546	}
547	
548	// dupNames returns the names appearing more than once in list.
549	func dupNames(list []string) []string {
550		seen := make(map[string]int)
551		var dups []string
552		for _, name := range list {
553			seen[name]++
554			if seen[name] == 2 {
555				dups = append(dups, name)
556			}
557		}
558		return dups
559	}
