21	// applyToFreshGraph applies plan to a fresh copy of the old graph and returns
22	// snapshots of both versions, so the batch report and the snapshot comparison
23	// describe exactly the same transition.
24	func applyToFreshGraph(t *testing.T, oldGraph map[string]*Lineage, plan Plan) (oldSnap, newSnap *SnapshotFile, batchReport *BatchReport) {
25		t.Helper()
26		oldSnap, err := BuildSnapshot(oldGraph)
27		if err != nil {
28			t.Fatalf("BuildSnapshot old graph unexpected error: %v", err)
29		}
30		// Rebuild the same graph from its canonical form so the apply cannot
31		// alias the snapshot's input.
32		fresh, err := UnmarshalGraphFile(mustMarshalGraph(t, oldGraph))
33		if err != nil {
34			t.Fatalf("re-read old graph unexpected error: %v", err)
35		}
36		batchReport, err = ApplyBatch(fresh, plan)
37		if err != nil {
38			t.Fatalf("ApplyBatch unexpected error: %v", err)
39		}
40		newSnap, err = BuildSnapshot(fresh)
41		if err != nil {
42			t.Fatalf("BuildSnapshot new graph unexpected error: %v", err)
43		}
44		return oldSnap, newSnap, batchReport
45	}
46	
47	func mustMarshalGraph(t *testing.T, graph map[string]*Lineage) []byte {
48		t.Helper()
49		data, err := MarshalGraphFile(graph)
50		if err != nil {
51			t.Fatalf("MarshalGraphFile unexpected error: %v", err)
52		}
53		return data
54	}
55	
56	// assertSameDatasetClassification fails unless the batch report and the
57	// compare report list exactly the same new, removed, and changed datasets.
58	func assertSameDatasetClassification(t *testing.T, batch *BatchReport, compare *CompareReport) {
59		t.Helper()
60		if !reflect.DeepEqual(batch.NewDatasets, compare.NewDatasets) {
61			t.Errorf("new datasets disagree: batch %v, compare %v", batch.NewDatasets, compare.NewDatasets)
62		}
63		if !reflect.DeepEqual(batch.RemovedDatasets, compare.RemovedDatasets) {
64			t.Errorf("removed datasets disagree: batch %v, compare %v", batch.RemovedDatasets, compare.RemovedDatasets)
65		}
66		if !reflect.DeepEqual(batch.ChangedDatasets, compare.ChangedDatasets) {
67			t.Errorf("changed datasets disagree: batch %v, compare %v", batch.ChangedDatasets, compare.ChangedDatasets)
68		}
69	}
70	
71	// TestBatchAndCompareAgreeOnDeleteRepoint is the headline convergence case:
72	// the old graph has root A with B depending on A and C depending on B; the
73	// batch deletes A, registers the new root D, and repoints B onto D while C is
74	// left alone. Both reports must list exactly new [D], removed [A], changed
75	// [B] — C is downstream impact, never a direct change. The reports keep their
76	// own extras: the batch report lists C as an affected downstream, and the
77	// comparison reports B and C switching root source A -> D.
78	func TestBatchAndCompareAgreeOnDeleteRepoint(t *testing.T) {
79		oldGraph := buildGraph(t, P("A"), P("B", "A"), P("C", "B"))
80		plan := Plan{
81			Changes:  []PlanChange{change("D"), change("B", "D")},
82			Removals: []string{"A"},
83		}
84	
85		// Preview against the pristine graph, then apply to a fresh copy so the
86		// comparison covers the identical transition.
87		preview, err := PreviewBatch(oldGraph, plan)
88		if err != nil {
89			t.Fatalf("PreviewBatch unexpected error: %v", err)
90		}
91		oldSnap, newSnap, applied := applyToFreshGraph(t, oldGraph, plan)
92		if !reflect.DeepEqual(preview, applied) {
93			t.Errorf("preview and apply reports differ:\n preview=%#v\n applied=%#v", preview, applied)
94		}
95	
96		compare := CompareSnapshots(oldSnap, newSnap)
97	
98		if got, want := applied.NewDatasets, []string{"D"}; !reflect.DeepEqual(got, want) {
99			t.Errorf("batch NewDatasets = %v, want %v", got, want)
100		}
101		if got, want := applied.RemovedDatasets, []string{"A"}; !reflect.DeepEqual(got, want) {
102			t.Errorf("batch RemovedDatasets = %v, want %v", got, want)
103		}
104		if got, want := applied.ChangedDatasets, []string{"B"}; !reflect.DeepEqual(got, want) {
105			t.Errorf("batch ChangedDatasets = %v, want %v", got, want)
106		}
107		assertSameDatasetClassification(t, applied, compare)
108	
109		// C keeps its direct upstream B, so it is not a direct change in either
110		// report; it is downstream impact in the batch report and a root-source
111		// change in the comparison.
112		if containsString(compare.ChangedDatasets, "C") {
113			t.Errorf("compare ChangedDatasets = %v, C must not be a direct change", compare.ChangedDatasets)
114		}
115		if got, want := applied.AffectedDownstreams, []string{"C"}; !reflect.DeepEqual(got, want) {
116			t.Errorf("batch AffectedDownstreams = %v, want %v", got, want)
117		}
118		wantRootChanges := []RootSourceChange{
119			{Dataset: "B", OldRoots: []string{"A"}, NewRoots: []string{"D"}},
120			{Dataset: "C", OldRoots: []string{"A"}, NewRoots: []string{"D"}},
121		}
122		if got := compare.RootSourceChanges; !reflect.DeepEqual(got, wantRootChanges) {
123			t.Errorf("compare RootSourceChanges = %v, want %v", got, wantRootChanges)
124		}
125	}
126	
127	// TestBatchAndCompareAgreeOnNoOpAndBoundaryCases pins the shared rule's
128	// boundaries on one transition: re-declaring an existing dataset with its
129	// current upstreams (even shuffled and duplicated) is NOT a change; a newly
130	// registered dataset is new even though it arrives with upstreams; clearing a
131	// dataset's upstreams makes it a root and is a change, not a removal; and a
132	// removal that names no existing dataset is a no-op.
133	func TestBatchAndCompareAgreeOnNoOpAndBoundaryCases(t *testing.T) {
134		// Roots A, F; B depends on A; C depends on B.
135		oldGraph := buildGraph(t, P("A"), P("F"), P("B", "A"), P("C", "B"))
136		plan := Plan{
137			Changes: []PlanChange{
138				change("B", "A", "A"), // same upstream set as before: no change
139				change("E", "F"),      // registered with an upstream: new, not changed
140				change("C"),           // upstreams cleared: changed, not removed
141			},
142			Removals: []string{"ghost"}, // does not exist: no-op, not reported
143		}
144	
145		if _, err := PreviewBatch(oldGraph, plan); err != nil {
146			t.Fatalf("PreviewBatch unexpected error: %v", err)
147		}
148		oldSnap, newSnap, applied := applyToFreshGraph(t, oldGraph, plan)
149		compare := CompareSnapshots(oldSnap, newSnap)
150	
151		if got, want := applied.NewDatasets, []string{"E"}; !reflect.DeepEqual(got, want) {
152			t.Errorf("batch NewDatasets = %v, want %v", got, want)
153		}
154		if got, want := applied.RemovedDatasets, []string{}; !reflect.DeepEqual(got, want) {
155			t.Errorf("batch RemovedDatasets = %v, want %v (removing a missing name is a no-op)", got, want)
156		}
157		if got, want := applied.ChangedDatasets, []string{"C"}; !reflect.DeepEqual(got, want) {
158			t.Errorf("batch ChangedDatasets = %v, want %v (a no-op re-declaration is not a change)", got, want)
159		}
160		assertSameDatasetClassification(t, applied, compare)
161	
162		// The no-op re-declaration of B must not surface anywhere as a change,
163		// and B keeps root source A through its retained upstream.
164		if containsString(compare.ChangedDatasets, "B") {
165			t.Errorf("compare ChangedDatasets = %v, B's upstreams are unchanged", compare.ChangedDatasets)
166		}
167		// C became a root: it is its own source now, so the comparison reports
168		// its root source changing A -> C, while the batch report counts C's
169		// downstream impact only through the seed rules (C is itself a seed).
170		wantRootChanges := []RootSourceChange{
171			{Dataset: "C", OldRoots: []string{"A"}, NewRoots: []string{"C"}},
172		}
173		if got := compare.RootSourceChanges; !reflect.DeepEqual(got, wantRootChanges) {
174			t.Errorf("compare RootSourceChanges = %v, want %v", got, wantRootChanges)
175		}
176	}
177	
178	// TestBatchAndCompareAgreeAcrossShuffledSemantics feeds the same transition
179	// through record order, upstream order, and duplicate-upstream noise and
180	// requires both reports to stay byte-identical to their canonical runs, so
181	// the shared classification cannot drift on inputs that differ only in
182	// spelling.
183	func TestBatchAndCompareAgreeAcrossShuffledSemantics(t *testing.T) {
184		oldGraph := buildGraph(t, P("A"), P("B", "A"), P("C", "B"))
185		plan := Plan{
186			Changes:  []PlanChange{change("D"), change("B", "D", "D")},
187			Removals: []string{"A"},
188		}
189	
190		_, _, canonical := applyToFreshGraph(t, oldGraph, plan)
191		canonicalCompare := CompareSnapshots(
192			mustBuildSnapshot(t, oldGraph),
193			mustBuildSnapshot(t, buildGraph(t, P("D"), P("B", "D"), P("C", "B"))),
194		)
195	
196		// Same plan semantics spelled differently: change records reordered, the
197		// duplicate upstream dropped.
198		shuffledPlan := Plan{
199			Changes:  []PlanChange{change("B", "D"), change("D")},
200			Removals: []string{"A"},
201		}
202		_, _, shuffled := applyToFreshGraph(t, oldGraph, shuffledPlan)
203		if !reflect.DeepEqual(canonical, shuffled) {
204			t.Errorf("equivalent plans produced different batch reports:\n canonical=%#v\n shuffled=%#v", canonical, shuffled)
205		}
206	
207		// Same final graph semantics spelled differently: record order and
208		// duplicate upstreams in the rebuilt graph file.
209		shuffledFinal, err := UnmarshalGraphFile([]byte(`{"datasets":[
210			{"name":"C","upstreams":["B"]},
211			{"name":"B","upstreams":["D","D"]},
212			{"name":"D","upstreams":[]}
213		]}`))
214		if err != nil {
215			t.Fatalf("re-read shuffled final graph unexpected error: %v", err)
216		}
217		shuffledCompare := CompareSnapshots(mustBuildSnapshot(t, oldGraph), mustBuildSnapshot(t, shuffledFinal))
218		if !reflect.DeepEqual(canonicalCompare, shuffledCompare) {
219			t.Errorf("equivalent graphs produced different compare reports:\n canonical=%#v\n shuffled=%#v", canonicalCompare, shuffledCompare)
220		}
221		assertSameDatasetClassification(t, shuffled, shuffledCompare)
222	}
223	
224	func mustBuildSnapshot(t *testing.T, graph map[string]*Lineage) *SnapshotFile {
225		t.Helper()
226		snap, err := BuildSnapshot(graph)
227		if err != nil {
228			t.Fatalf("BuildSnapshot unexpected error: %v", err)
229		}
230		return snap
231	}
