243	// TestCLITraceDeepConvergingBranchesByteStable exercises the path-selection
244	// rule through deep lineage end to end. T reaches R1 and R2 along two
245	// four-relation branches that merge at M:
246	//
247	//	T -> A -> Z -> M -> {R1,R2}
248	//	T -> B -> C -> M -> {R1,R2}
249	//
250	// The branch via A wins at the first differing name (A < B) even though the
251	// other branch passes through C < Z. The complete JSON report must be
252	// byte-for-byte identical when the same graph is reshuffled (record order,
253	// upstream order, duplicate upstreams, whitespace), including a disconnected
254	// branch, and must exactly match the golden bytes: sources ordered by root
255	// name byte order and full path arrays from the query object to each root.
256	func TestCLITraceDeepConvergingBranchesByteStable(t *testing.T) {
257		deepGraph := `{"datasets":[
258			{"name":"T","upstreams":["B","A"]},
259			{"name":"A","upstreams":["Z"]},
260			{"name":"Z","upstreams":["M"]},
261			{"name":"B","upstreams":["C"]},
262			{"name":"C","upstreams":["M"]},
263			{"name":"M","upstreams":["R2","R1"]},
264			{"name":"R1","upstreams":[]},
265			{"name":"R2","upstreams":[]},
266			{"name":"U","upstreams":["X"]},
267			{"name":"X","upstreams":[]}
268		]}`
269		shuffled := `{ "datasets" : [
270			{"upstreams":[],"name":"X"},
271			{"name":"U","upstreams":["X","X"]},
272			{"upstreams":[],"name":"R2"},
273			{"name":"R1","upstreams":[]},
274			{"upstreams":["R1","R2","R1"],"name":"M"},
275			{"name":"C","upstreams":["M","M"]},
276			{"upstreams":["M"],"name":"Z"},
277			{"name":"B","upstreams":["C"]},
278			{"name":"A","upstreams":["Z"]},
279			{"upstreams":["A","B","B","A"],"name":"T"}
280		] }`
281	
282		s1 := snapshotForTrace(t, deepGraph)
283		s2 := snapshotForTrace(t, shuffled)
284	
285		out1, stderr, exit := captureStdout(t, func() int { return run([]string{"trace", s1, "T"}) })
286		if exit != 0 {
287			t.Fatalf("trace s1: %s", stderr)
288		}
289		out2, stderr, exit := captureStdout(t, func() int { return run([]string{"trace", s2, "T"}) })
290		if exit != 0 {
291			t.Fatalf("trace s2: %s", stderr)
292		}
293		if out1 != out2 {
294			t.Errorf("equivalent deep snapshots produced different reports:\n%s\n%s", out1, out2)
295		}
296	
297		// The content identifier comes from the snapshot actually read; the rest
298		// is the exact golden report, pinning formatting, key order, root-name
299		// ordering, and the full name arrays.
300		snap, err := chainledger.ParseSnapshot([]byte(readFile(t, s1)))
301		if err != nil {
302			t.Fatalf("parse snapshot: %v", err)
303		}
304		golden := "{\n" +
305			"  \"contentId\": " + fmt.Sprintf("%q", snap.ContentID) + ",\n" +
306			"  \"dataset\": \"T\",\n" +
307			"  \"sources\": [\n" +
308			"    {\n" +
309			"      \"root\": \"R1\",\n" +
310			"      \"path\": [\n" +
311			"        \"T\",\n" +
312			"        \"A\",\n" +
313			"        \"Z\",\n" +
314			"        \"M\",\n" +
315			"        \"R1\"\n" +
316			"      ]\n" +
317			"    },\n" +
318			"    {\n" +
319			"      \"root\": \"R2\",\n" +
320			"      \"path\": [\n" +
321			"        \"T\",\n" +
322			"        \"A\",\n" +
323			"        \"Z\",\n" +
324			"        \"M\",\n" +
325			"        \"R2\"\n" +
326			"      ]\n" +
327			"    }\n" +
328			"  ]\n" +
329			"}\n"
330		if out1 != golden {
331			t.Errorf("deep trace report differs from golden:\n got: %q\nwant: %q", out1, golden)
332		}
333	}
334	
335	// traceSharedPrefixGraph is the CLI counterpart of the report-independence
336	// fixture in the core package: T and U both reach roots R1 and R2 through the
337	// common intermediate M, so both of T's paths share the prefix [T M], and X is
338	// a disconnected root.
339	const traceSharedPrefixGraph = `{"datasets":[
340		{"name":"T","upstreams":["M"]},
341		{"name":"U","upstreams":["M"]},
342		{"name":"M","upstreams":["R1","R2"]},
343		{"name":"R1","upstreams":[]},
344		{"name":"R2","upstreams":[]},
345		{"name":"X","upstreams":[]}
346	]}`
