348	// runTraceCommand invokes `trace snapPath dataset` and returns its stdout,
349	// stderr, and exit code.
350	func runTraceCommand(t *testing.T, snapPath, dataset string) (stdout, stderr string, exit int) {
351		t.Helper()
352		return captureStdout(t, func() int {
353			return run([]string{"trace", snapPath, dataset})
354		})
355	}
