357	// TestCLITraceReportsAreIndependentAcrossInvocations pins the command-line
358	// shape of the report-independence guarantee: two successful trace outputs for
359	// the same query and one for another downstream through the same shared
360	// intermediate each keep representing the result at their own invocation, and
361	// the read-only command never modifies the snapshot. A caller editing one
362	// emitted JSON report cannot affect another invocation's report because each
363	// run computes from the frozen snapshot file, which these later runs must find
364	// byte-for-byte unchanged.
365	func TestCLITraceReportsAreIndependentAcrossInvocations(t *testing.T) {
366		snapPath := snapshotForTrace(t, traceSharedPrefixGraph)
367		snapBytes := readFile(t, snapPath)
368	
369		outT1, stderr, exit := runTraceCommand(t, snapPath, "T")
370		if exit != 0 {
371			t.Fatalf("first trace T exit = %d, stderr = %s", exit, stderr)
372		}
373		outT2, stderr, exit := runTraceCommand(t, snapPath, "T")
374		if exit != 0 {
375			t.Fatalf("second trace T exit = %d, stderr = %s", exit, stderr)
376		}
377		outU, stderr, exit := runTraceCommand(t, snapPath, "U")
378		if exit != 0 {
379			t.Fatalf("trace U exit = %d, stderr = %s", exit, stderr)
380		}
381	
382		// Repeated results are byte-identical: every report is computed from the
383		// same frozen snapshot, so display edits of one copy can never reach later
384		// output.
385		if outT1 != outT2 {
386			t.Errorf("repeated T traces differ:\n%s\n%s", outT1, outT2)
387		}
388	
389		// The other downstream through the same shared intermediate reports its
390		// own query name and its own complete paths.
391		var reportU chainledger.TraceReport
392		if err := json.Unmarshal([]byte(outU), &reportU); err != nil {
393			t.Fatalf("trace U stdout is not valid JSON: %v\n%s", err, outU)
394		}
395		if reportU.Dataset != "U" {
396			t.Errorf("U report Dataset = %q, want %q", reportU.Dataset, "U")
397		}
398		wantU := []chainledger.SourceTrace{
399			{Root: "R1", Path: []string{"U", "M", "R1"}},
400			{Root: "R2", Path: []string{"U", "M", "R2"}},
401		}
402		if !reflect.DeepEqual(reportU.Sources, wantU) {
403			t.Errorf("U Sources = %+v, want %+v", reportU.Sources, wantU)
404		}
405		var reportT chainledger.TraceReport
406		if err := json.Unmarshal([]byte(outT1), &reportT); err != nil {
407			t.Fatalf("trace T stdout is not valid JSON: %v\n%s", err, outT1)
408		}
409		wantT := []chainledger.SourceTrace{
410			{Root: "R1", Path: []string{"T", "M", "R1"}},
411			{Root: "R2", Path: []string{"T", "M", "R2"}},
412		}
413		if !reflect.DeepEqual(reportT.Sources, wantT) {
414			t.Errorf("T Sources = %+v, want %+v", reportT.Sources, wantT)
415		}
416	
417		// The snapshot file is still byte-for-byte the frozen input.
418		if got := readFile(t, snapPath); got != snapBytes {
419			t.Errorf("snapshot changed across trace invocations:\n got %s\nwant %s", got, snapBytes)
420		}
421	}
422	
423	// TestCLITraceSuccessThenErrorsLeavesSnapshotAndRequeryUntouched pins, end to
424	// end, the boundary around rejected queries: after successful reports are in
425	// hand, an empty name and an unknown name keep failing with the existing error
426	// categories and empty stdout, while the snapshot file stays untouched and a
427	// later successful query still reports the frozen sources and paths.
428	func TestCLITraceSuccessThenErrorsLeavesSnapshotAndRequeryUntouched(t *testing.T) {
429		snapPath := snapshotForTrace(t, traceSharedPrefixGraph)
430		snapBytes := readFile(t, snapPath)
431	
432		okOut, stderr, exit := runTraceCommand(t, snapPath, "T")
433		if exit != 0 {
434			t.Fatalf("trace T exit = %d, stderr = %s", exit, stderr)
435		}
436		rootOut, stderr, exit := runTraceCommand(t, snapPath, "R1")
437		if exit != 0 {
438			t.Fatalf("trace R1 exit = %d, stderr = %s", exit, stderr)
439		}
440	
441		for _, dataset := range []string{"", "ghost"} {
442			stdout, stderr, exit := runTraceCommand(t, snapPath, dataset)
443			if exit == 0 {
444				t.Fatalf("trace %q succeeded, want failure", dataset)
445			}
446			if stdout != "" {
447				t.Errorf("trace %q stdout = %q, want empty", dataset, stdout)
448			}
449			if !strings.Contains(stderr, snapPath) {
450				t.Errorf("trace %q stderr = %q, must name the snapshot file", dataset, stderr)
451			}
452		}
453	
454		// The snapshot file is unchanged by the rejected queries.
455		if got := readFile(t, snapPath); got != snapBytes {
456			t.Errorf("snapshot changed after rejected queries:\n got %s\nwant %s", got, snapBytes)
457		}
458	
459		// A later successful query returns the frozen result byte-for-byte,
460		// including the root's single-element path.
461		retryT, stderr, exit := runTraceCommand(t, snapPath, "T")
462		if exit != 0 {
463			t.Fatalf("retry trace T exit = %d, stderr = %s", exit, stderr)
464		}
465		if retryT != okOut {
466			t.Errorf("retry trace T differs from the earlier success:\n got %s\nwant %s", retryT, okOut)
467		}
468		retryRoot, stderr, exit := runTraceCommand(t, snapPath, "R1")
469		if exit != 0 {
470			t.Fatalf("retry trace R1 exit = %d, stderr = %s", exit, stderr)
471		}
472		if retryRoot != rootOut {
473			t.Errorf("retry trace R1 differs from the earlier success:\n got %s\nwant %s", retryRoot, rootOut)
474		}
475		var rootReport chainledger.TraceReport
476		if err := json.Unmarshal([]byte(retryRoot), &rootReport); err != nil {
477			t.Fatalf("trace R1 stdout is not valid JSON: %v\n%s", err, retryRoot)
478		}
479		if want := []chainledger.SourceTrace{{Root: "R1", Path: []string{"R1"}}}; !reflect.DeepEqual(rootReport.Sources, want) {
480			t.Errorf("R1 Sources = %+v, want %+v", rootReport.Sources, want)
481		}
482	}
