// sortStrings is the plain sort helper kept under a local name so this file's
// intent reads without an import block surprise in each assertion below.
func sortStrings(s []string) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j-1] > s[j]; j-- {
			s[j-1], s[j] = s[j], s[j-1]
		}
	}
}

